  "jxg.prompt_intro":       "Je genereert een KLASSIEKE, ZELFSTANDIGE JSXGraph-grafiek (alleen te testen in een\nbrowser). Maak je GEEN zorgen over STACK/Moodle: ik zet je\ncode daarna zelf om (syntax [[jsxgraph]], divid, {#…#}) — je hoeft die niet te kennen.",
  "jxg.prompt_rules_header":"━━ REGELS ━━",
  "jxg.prompt_rule1":       "1. Volledige, zelfstandige structuur:\n   <div id=\"box\" style=\"width:{w};height:{h};\"></div>\n   <script src=\"https://cdn.jsdelivr.net/npm/jsxgraph/distrib/jsxgraphcore.js\"></script>\n   <script>\n   var board = JXG.JSXGraph.initBoard('box', {…});\n   … jouw code …\n   </script>",
  "jxg.prompt_rule2":       "2. Noem de board-variabele EXACT \"board\" en de container EXACT\n   \"box\" (zoals in het skelet hieronder).",
  "jxg.prompt_rule3":       "3. Als je een van de hieronder vermelde variabelen gebruikt, declareer die dan\n   met een voorbeeldwaarde ÉN het commentaar // POOLVAR: naam op DEZELFDE regel\n   (bv. var a = 3; // POOLVAR: a) — daarmee kan ik hem na de conversie\n   automatisch koppelen.",
  "jxg.prompt_rule4":       "4. Omsluit de tekening met board.suspendUpdate() / board.unsuspendUpdate().",
  "jxg.prompt_rule5_interactive": "5. Deze grafiek is INTERACTIEF: de punten die de leerling moet kunnen verslepen\n   zijn gewone, versleepbare JSXGraph-punten (GEEN fixed:true). Voeg meteen na\n   de regel board.create('point', …) van ELK interactief punt een\n   commentaar // BIND: variabelenaam toe (bv. // BIND: ans1) dat aangeeft met welke\n   STACK-antwoordvariabele het overeenkomt — de koppeling\n   stack_jxg.bind_point doe ik zelf na de conversie.",
  "jxg.prompt_rule5_display":     "5. Deze grafiek is ENKEL WEERGAVE (niet interactief): alle JSXGraph-objecten\n   MOETEN {fixed:true, highlight:false, visible:true} hebben\n   (alle drie — STACK heeft naast fixed:true ook visible:true nodig).",
  "jxg.prompt_config_header":"━━ CONFIGURATIE VAN HET ASSENSTELSEL (exact volgen) ━━",
  "jxg.prompt_window":      "Venster: x van {xmin} tot {xmax}, y van {ymin} tot {ymax}",
