  "jxg.prompt_var_line":    "  {n}  →  var {n} = <voorbeeldwaarde>; // POOLVAR: {n}",
  "jxg.prompt_no_vars":     "(geen variabele gedefinieerd in de pool voor deze toets)",
  "jxg.prompt_skeleton_header": "━━ REFERENTIESKELET (gebruik exact deze config voor initBoard) ━━",
  "jxg.prompt_request_header":  "━━ VERZOEK ━━",
