  "jxg.prompt_footer":      "Antwoord ALLEEN met de code (div + script), klaar om te plakken en te testen in\neen browser, omsloten door een markdown-codeblok (```html aan het begin, ```\naan het einde) — anders voeren sommige chatinterfaces de HTML/JS uit\nin plaats van het als tekst te tonen. Geen uitleg ervoor of erna.",
