  "match.add_btn":          "+ Toevoegen",
  "match.connect_title":    "Creëer de verwachte verbindingen",
  "match.connect_hint":     "Klik op een item aan de linkerkant en vervolgens op een item aan de rechterkant om ze te koppelen.",
  "match.fbgen_auto_desc":  "De correctie gebeurt automatisch: er wordt een percentage correct tot stand gebrachte verbindingen berekend, met een herinnering voor verbindingsfouten.",

  "match.prompt_ctx_base":       "{matter} niveau {level}",
  "match.prompt_ctx_sous":       ", subvak « {sous} »",
  "match.prompt_ctx_chap":       ", hoofdstuk « {chap} »",
  "match.prompt_role":           "### ROL\nJe bent een ervaren onderwijskundig ontwerper, gespecialiseerd in interactieve toetsvormen (Matching Questions). Je taak is om een koppelopdracht te genereren, gestructureerd als JSON.",
  "match.prompt_consigne_title": "### OPDRACHT",
  "match.prompt_consigne":       "Genereer een opdracht van het type \"Koppelen\" over het volgende onderwerp: {subject} voor een oefening in {ctx}.",
  "match.prompt_bullet_left":    "De linkerkolom (leftItems) bevat concepten, concrete voorbeelden, waarden of praktijkgevallen.",
  "match.prompt_bullet_right":   "De rechterkolom (rightItems) bevat algemene categorieën, definities, eigenschappen of drempelwaarden.",
  "match.prompt_bullet_constraint": "VERPLICHTE DIDACTISCHE BEPERKING (GEEN 1-OP-1): De opdracht mag GEEN eenvoudige lineaire koppeling zijn. Ontwerp de opdracht zo dat een element rechts gekoppeld is aan meerdere elementen links (Veel-op-Eén-relatie), of dat een element links verbonden is met meerdere eigenschappen rechts (Veel-op-Veel).",
  "match.prompt_bullet_lang":    "De te gebruiken taal is {lang}.",
  "match.prompt_tech_title":     "### STRIKTE TECHNISCHE VOORWAARDEN",
  "match.prompt_tech1":          "1. UITVOERFORMAAT: Uitsluitend zuivere JSON (geen overbodige tekst, geen markdown-codeblokken, alleen het JSON-object).",
  "match.prompt_tech2":          "2. STRUCTUUR VAN DE ITEMS: Elk object in \"leftItems\" en \"rightItems\" moet verplicht deze exacte structuur hebben:",
  "match.prompt_tech3":          "3. STRUCTUUR VAN DE CONNECTIONS: De array \"connections\" moet een array van numerieke indexparen zijn (beginnend bij 0). Voorbeeld: [[0, 0], [1, 2], [2, 2]]. Gebruik geen objecten met de sleutels leftId/rightId.",
  "match.prompt_tech4":          "4. ASYMMETRIE: Het aantal elementen links en rechts moet verschillend zijn. Eenzelfde index rechts MOET meerdere keren voorkomen in de array \"connections\" om de niet-lineaire structuur te bevestigen.",
  "match.prompt_tech5":          "5. JSON-ESCAPING: verdubbel binnen de strings elke backslash (\\\\) en escape interne aanhalingstekens (\\\"). Escape aanhalingstekens in HTML-attributen correct. De JSON moet zo geldig zijn.",
  "match.prompt_example_title":  "### VOORBEELD VAN DE VERWACHTE STRUCTUUR (asymmetrisch Veel-op-Eén-model)",
  "match.prompt_example_left1":  "Hond",
  "match.prompt_example_left2":  "Arend",
  "match.prompt_example_left3":  "Kat",
  "match.prompt_example_right1": "Zoogdieren",
  "match.prompt_example_right2": "Vogels",
  "match.prompt_final_title":    "### EINDCONTROLE (voor het antwoorden)",
  "match.prompt_final_check":    "Controleer dat: (1) de JSON syntactisch geldig is; (2) alle backslashes verdubbeld en interne aanhalingstekens escaped zijn; (3) de structuur (id/html/text, connections als indexparen) gerespecteerd wordt; (4) asymmetrie aanwezig is; (5) er geen tekst buiten het JSON-blok staat. Als je niet aan deze voorwaarden kunt voldoen, geef dan een leeg JSON-object {} terug.",
