  "lim.fbgen_auto_desc":   "De correctie (formule, waarde) wordt automatisch gegenereerd volgens de gekozen instellingen in Config.",
  "lim.banniere":          "Grenzen",
  "lim.calc_limite":       "Bereken de limiet:",
  "lim.taper_inf_ou_moins_inf": "Typ <code>inf</code> voor \\(+\\infty\\) of <code>-inf</code> voor \\(-\\infty\\).",
  "lim.taper_inf":         "Typ <code>inf</code> voor \\(+\\infty\\).",
  "lim.taper_moins_inf":   "Typ <code>-inf</code> voor \\(-\\infty\\).",
  "lim.calc_limite_indetermination": "Bereken (onbepaaldheid verwijderen):",
  "lim.calc_limite_droite": "Bereken de limiet aan de rechterkant:",
  "lim.calc_limite_gauche": "Bereken de limiet aan de linkerkant:",
  "lim.fb_wrong_fixe":     "<strong>Methode</strong>: Probeer eerst directe vervanging. Als we een onbepaalde vorm verkrijgen (0/0, ∞/∞, ∞−∞...), factoreer of vereenvoudig dan de uitdrukking voordat je de limiet neemt.<br>Verwacht antwoord: {@{tavar}@}.",
  "lim.fbgen_fixe":        "De gevraagde limiet is {@{tavar}@}. Controleer de directe vervanging en, in het geval van een onbepaalde vorm, factoriseer/vereenvoudig voordat u besluit.",
  "lim.fb_wrong_plus_inf": "<strong>Methode</strong>: voor een limiet in \\(+\\infty\\) van een quotiënt van polynomen, vergelijken we de graden van de teller en de noemer (equivalent aan het ontbinden van de dominante macht aan beide kanten).<br>Hier heeft de teller \\({@{numvar}@}\\) graad {@{degnvar}@} (dominante coëfficiënt {@{lcnvar}@}), en de noemer \\({@{denvar}@}\\) heeft graad {@{degdvar}@} (dominante coëfficiënt {@{lcdvar}@}).<br>• deg(num) < deg(den) → limiet 0.<br>• deg(num) = deg(den) → limiet = verhouding van de dominante coëfficiënten.<br>• deg(num) > deg(den) → oneindige limiet.<br>Conclusie: de limiet is {@{tavar}@} waard.",
  "lim.fbgen_plus_inf":    "\\(\\displaystyle\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\): teller van graad {@{degnvar}@} (dominante coëfficiënt {@{lcnvar}@}), noemer van graad {@{degdvar}@} (dominante coëfficiënt {@{lcdvar}@}).<br>\\(\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_moins_inf":"<strong>Methode</strong>: voor een limiet in \\(-\\infty\\) van een quotiënt van polynomen vergelijken we de graden van de teller en de noemer.<br>Hier heeft de teller \\({@{numvar}@}\\) graad {@{degnvar}@} (dominante coëfficiënt {@{lcnvar}@}) en de noemer \\({@{denvar}@}\\) heeft graad {@{degdvar}@} (dominante coëfficiënt {@{lcdvar}@}).<br>• deg(num) < deg(den) → limiet 0.<br>• deg(num) = deg(den) → limiet = verhouding van de dominante coëfficiënten.<br>• deg(num) > deg(den) → oneindige limiet (let op inloggen \\(-\\infty\\)).<br>Conclusie: de limiet is {@{tavar}@}.",
  "lim.fbgen_moins_inf":   "\\(\\displaystyle\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\): teller van graad {@{degnvar}@} (dominante coëfficiënt {@{lcnvar}@}), noemer van graad {@{degdvar}@} (dominante coëfficiënt {@{lcdvar}@}).<br>\\(\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_point_fini":"<strong>Methode</strong>: teller en noemer vallen beide weg op \\(x={@{avar}@}\\) (onbepaalde vorm 0/0). We ontbinden \\((x-{@{avar}@})\\) in de teller: \\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\).<br>We vereenvoudigen met de identieke factor in de noemer: \\(\\frac{(x-{@{avar}@})({@{qvar}@})}{x-{@{avar}@}}={@{qvar}@}\\).<br>Het moet nog worden geëvalueerd in \\(x={@{avar}@}\\): {@{tavar}@}.",
  "lim.fbgen_point_fini":  "Ontbind \\((x-{@{avar}@})\\) in de teller (\\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\)), en vereenvoudig vervolgens met de noemer: wat overblijft is \\({@{qvar}@}\\).<br>Evalueren in \\(x={@{avar}@}\\) geeft \\(\\lim={@{tavar}@}\\).",
  "lim.fb_wrong_droite":   "<strong>Methode</strong>: we bepalen de verandering van variabele \\(u=x-{@{avar}@}\\); wanneer \\(x\\to{@{avar}@}^+\\), hebben we \\(u\\to 0^+\\) (u blijft positief).<br>De uitdrukking wordt \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\).<br>Wanneer \\(u\\to 0^+\\), \\(\\sqrt{u}\\to 0^+\\) dus \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fbgen_droite":      "Stel \\(u=x-{@{avar}@}\\to 0^+\\ in): de expressie wordt \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fb_wrong_gauche":   "<strong>Methode</strong>: we stellen \\(u={@{avar}@}-x\\); wanneer \\(x\\to{@{avar}@}^-\\), hebben we \\(u\\to 0^+\\), en \\(x-{@{avar}@}=-u\\).<br>De uitdrukking wordt \\(\\frac{\\sqrt{u}}{-u}=-\\frac{1}{\\sqrt{u}}\\).<br>Wanneer \\(u\\to 0^+\\), \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\), dus de uitdrukking neigt naar \\(-\\infty\\).",
  "lim.fbgen_gauche":      "Stel \\(u={@{avar}@}-x\\to 0^+\\ in, met \\(x-{@{avar}@}=-u\\): de expressie wordt \\(\\frac{\\sqrt{u}}{-u}=-\\frac{1}{\\sqrt{u}}\\to-\\infty\\).",

