  "osc.genfb_reponses_attendues": "🔑 Verwachte reacties",
  "osc.genfb_q1_periode": "Q1-periode:",
  "osc.genfb_periode_explanation": "De periode is de tijd die een cyclisch fenomeen nodig heeft om zichzelf op identieke wijze te reproduceren. Op deze spanning {@ta{X}_type_text@} vinden we met de tijdcursors T = {@1.0*ta{X}_T@}",
  "osc.genfb_q2_frequence": "Q2 Frequentie:",
  "osc.genfb_frequence_explanation": "Frequentie is het aantal keren dat een fenomeen per seconde voorkomt, dit wordt berekend met \\[ f = \\frac{1}{T} \\]",
  "osc.genfb_frequence_calcul": "We hebben daarom \\[ f= \\frac {1}{ {@1.0*ta{X}_T@} }= {@ta{X}_fq@} \\]",
  "osc.consigne_y_decharge": "Gebruik <span style=\"color:#b91c1c;font-weight:bold;\">■ Y</span> om de grootte van de initiële spanning \\(E\\) (tussen het lager en de onderste lijn) te meten.",
  "osc.consigne_y_charge": "Gebruik <span style=\"color:#b91c1c;font-weight:bold;\">■ Y</span> om de grootte van de eindspanning \\(E\\) (tussen het lager en de onderste lijn) te meten.",
