  "osc.genfb_tau_explanation": "Door te meten tussen \\(t=0\\) en het punt dat overeenkomt met {pct} van de spanning, vinden we \\(\\tau\\) = {@ta{X}_tau@}.",
  "osc.genfb_q2_tension": "Q2 Spanning {modus}:",
  "osc.genfb_tension_explanation": "Door het spanningsniveau te meten met de Y-cursors, vinden we \\(E\\) = {@ta{X}_E@}.",
  "osc.retard_intro": "We visualiseren het signaal van de zender (Kanaal A, <span style=\"color:#2563eb;font-weight:bold;\">Blauw</span>) en het signaal van de ontvanger (Kanaal B, <span style=\"color:#dc2626;font-weight:bold;\">Rood</span>).",
  "osc.retard_determinez": "Bepaal met behulp van de tijdschuifregelaars (■ X):",
  "osc.retard_li_frequence": "De frequentie van het uitgezonden ultrasone geluid \\(f\\).",
  "osc.retard_li_delta_t": "De tijdsvertraging \\(\\Delta t\\) tussen verzending en ontvangst.",
  "osc.label_frequence_ultrasons": "1. Echografiefrequentie \\(f\\):",
  "osc.label_retard_temporel": "2. Tijdvertraging \\(\\Delta t\\):",
  "osc.preview_retard": "📡 Oscilloscoop — Ultrasone vertraging (2 kanalen)",
  "osc.fb_freq_unite_ko_retard": "<strong>Frequentie:</strong> de eenheid is onjuist (verwacht in SI-basis: {@teacher_unit_f{X}/2@}).",
  "osc.fb_freq_correcte_retard": "<strong>Frequentie:</strong> correct.",
  "osc.fb_freq_trap_salve": "<strong>Frequentie:</strong> je hebt de periode van de burst gemeten (de totale omhullende), niet de periode van het hoogfrequente ultrasone signaal.",
  "osc.fb_freq_valeur_ko_retard": "<strong>Frequentie:</strong> de numerieke waarde of precisie is onjuist. Meet nauwkeurig de afstand van EEN kleine schommel.",
  "osc.fb_retard_unite_ko": "<strong>Vertraging:</strong> de eenheid is onjuist (verwacht in SI-basis: {@teacher_unit_dt{X}/2@}).",
  "osc.fb_retard_correct": "<strong>Vertraging:</strong> correct.",
  "osc.fb_retard_trap_periode": "<strong>Vertraging:</strong> u heeft de periode van het ultrasone signaal (\\(T = 1/f\\)) berekend en ingevoerd in plaats van de tijdsvertraging tussen verzending en ontvangst.",
  "osc.fb_retard_trap_demi_periode": "<strong>Vertraging:</strong> je hebt de helft van de signaalperiode (\\(T/2\\)) berekend in plaats van de tijdsvertraging tussen bursts.",
  "osc.fb_retard_valeur_ko": "<strong>Vertraging:</strong> de numerieke waarde of precisie is onjuist. Plaats één cursor op het begin van de blauwe burst (verzending) en de andere op het begin van de rode burst (ontvangst).",
  "osc.genfb_q1_frequence_retard": "Q1 Frequentie:",
  "osc.genfb_frequence_retard_explanation": "Door EEN periode van het hoogfrequente signaal (de kleine oscillaties) te meten, vinden we \\(f\\) = {@ta{X}_fc@}.",
  "osc.genfb_q2_retard": "Q2 Tijdvertraging:",
  "osc.genfb_retard_explanation": "Door één cursor op het begin van de blauwe burst te plaatsen en de andere op het begin van de rode burst, meten we \\(\\Delta t\\) = {@ta{X}_dt@}.",
  "diff.info_fente_simple_ecran": "Enkele sleuf, directe meting op de figuur. De leerling beweegt het dradenkruis over de punten om de breedte l van het centrale punt te meten en leidt hieruit de lambda af.",
  "diff.info_fente_simple_capteur": "Enkele sleuf, sensormeting. Het cijfer wordt weergegeven en er wordt een sensor toegevoegd die de intensiteit I(y) = sinc²(beta) meet; de leerling meet l op deze curve.",
  "diff.info_fente_double_ecran": "Twee spleten, directe meting op de randfiguur (sinc² diffractie-omhulsel x cos² interferentie). De leerling meet de grenslijn i en de breedte l van de centrale vlek.",
  "diff.info_fente_double_capteur": "Twee slots, sensormeting. Het randpatroon wordt weergegeven en voor de meting wordt een intensiteitscurve I(y) = sinc²(alpha) x cos²(beta) toegevoegd.",
  "diff.info_young_ecran": "Jonge gaten, directe meting in figuur 2D (luchtige plek x cos²). De leerling beweegt het dradenkruis over de ringen/franjes om de interfringe te meten.",
  "diff.info_young_capteur": "Jonge gaten, sensormeting. De 2D-figuur wordt weergegeven en een 1D-dwarsdoorsnede van de intensiteit langs één as wordt toegevoegd voor metingen bij de sensor.",
  "diff.info_trou_circulaire_ecran": "Rond gat, directe meting in figuur 2D (luchtige plek). De leerling beweegt het dradenkruis over de eerste donkere ring om de straal r van de centrale vlek te meten.",
  "diff.info_trou_circulaire_capteur": "Rond gat, sensormeting. De 2D-figuur wordt weergegeven en een 1D-radiaal gedeelte van de intensiteit wordt toegevoegd voor de sensormeting.",
  "diff.info_trou_carre_ecran": "Vierkant gat, directe meting in figuur 2D (centrale vierkante kruisvlek). De leerling verplaatst het dradenkruis om de breedte l van de centrale plek te meten.",
  "diff.info_trou_carre_capteur": "Vierkant gat, sensormeting. Figuur 2D wordt weergegeven en een curve I(y) van een sensor wordt toegevoegd om de breedte l van de centrale vlek te meten.",
