  "diff.consigne_airy_circ_capteur": "<p>De Airy-vlek is hierboven weergegeven. Hieronder wordt de radiale doorsnede I(r) van een sensor weergegeven: verplaats het dradenkruis op de curve om de straal r van het centrale punt te meten.</p>",
