  "log.ordre_3vars_desc":     "Bij 3 variabelen is de volgorde P (hoge orde) → Q → R (lage orde). Het lijkt erop dat je de volgorde hebt omgekeerd.",
  "log.ordre_2vars_desc":     "Je hebt de tabel gevuld beginnend met P=1, Q=1 (van boven naar beneden), terwijl deze gevuld moet worden beginnend met P=0, Q=0 (van onder naar boven).",
  "log.table_fallback_desc":  "Controleer stap voor stap de beoordeling van elke operator. Herinnering:<br>• De implicatie \\(P \\naar Q\\) is <u>alleen</u> onwaar als P waar is en Q onwaar.<br>• De NEE is eerst van toepassing.",
  "log.identifier_instr":     "Welke logische uitdrukking komt overeen met de volgende waarheidstabel?",
