  "log.identifier_ok_desc":   "Je hebt de logische uitdrukking correct geïdentificeerd aan de hand van de waarheidstabel.",
  "log.identifier_neg_desc":  "De gekozen expressie komt exact overeen met de <strong>inverse</strong> van de gevraagde tabel (0 en 1 zijn gepermuteerd). Controleer of je het niet hebt verward met de ontkenning van de stelling.",
  "log.identifier_fallback_desc": "Om de juiste uitdrukking te vinden, zoekt u de regels waar het resultaat <strong>1</strong> is en leidt u de belangrijkste logische verbinding af:<br>• Als alleen (1,1) 1 geeft → <em>EN</em><br>• Als alleen (0,0) 0 geeft → <em>OF</em><br>• Als alleen (1,0) 0 geeft → <em>IMPLICIED</em>",
