  "log.inter_fallback_desc":  "Ga kolom voor kolom te werk, van links naar rechts. Controleer elke operator afzonderlijk. Herinnering:<br>• <code>NOT</code>: keert 0 en 1 om<br>• <code>AND</code>: waarde 1 alleen als beide operanden 1 waard zijn<br>• <code>OR</code>: waarde 0 alleen als beide operanden 0 waard zijn<br>• <code>IMPLIES</code>: waarde 0 alleen als links=1 en rechts=0",
