  "cpx.fbdetail_desc":          "Elk scenario genereert meerdere correctietakken (PRT). Bewerk de tekst die voor elke casus hieronder aan de leerling wordt weergegeven, vooraf ingevuld met standaardfeedback.",
  "cpx.fbdetail_warn":          "⚠ Deze teksten worden elke keer dat u op “Opslaan” klikt, opnieuw gegenereerd. Om een ​​PRT-knooppunt na het opslaan te retoucheren zonder deze velden opnieuw te hoeven doorlopen, gebruikt u de knop “🌿 PRT Tree” onderaan het venster. Maar als u de configuratie daarna opnieuw opslaat, wordt dit handmatige retoucheren overschreven door de hier gedefinieerde tekst.",
  "cpx.correction_generale_lbl":"Algemene correctie",
