  "rx.fb_calc_cwrong_method":   "Methode: bij de equivalentie zijn de uitgewisselde hoeveelheden stof evenredig met de elektronen: n₁·C₁·Veq = n₂·C₂·V₂, dus C₂ = (n₁·C₁·Veq)/(n₂·V₂).",
