  "rx.method_demi_ewrong":      "Bij de halve equivalentie zijn de concentraties van de twee vormen van het getitreerde koppel gelijk ([Ox₂] = [Red₂]): in de Nernst-relatie valt de logaritmische term weg, dus <strong>E = E°₂</strong>.",
  "rx.method_demi_label":       "Halve equivalentie: V = Veq/2 = {v} mL, E = E°₂ = {e2} V",
  "rx.method_double_vwrong":    "Het dubbele-equivalentiepunt komt overeen met <strong>V = 2 × Veq</strong>: het toegevoegde overschot titrant is dan gelijk aan de oorspronkelijke hoeveelheid getitreerde soort.",
  "rx.method_double_ewrong":    "In dit overschot zijn de concentraties van de twee vormen van het titrantkoppel gelijk ([Ox₁] = [Red₁]): volgens Nernst geldt <strong>E = E°₁</strong>.",
