  "opt.err_oa_eq_f_s1": "OA = −f\': het object is scherp → beeld op oneindig (niet representatief).",
  "opt.err_oa_eq_f_s2": "OA = -f\': het object is scherpgesteld — beeld op oneindig (niet representatief).",
  "opt.fb_ok_title": "✅ <strong>Goede positie!</strong>",
