  "opt.info_lentille_convergente": "✏️ De leerling tekent minstens twee van de drie bijzondere stralen vanuit B met de werkbalk (straal 2 klikken, straal // as, parallelle straal 3 klikken), en construeert vervolgens het punt B' door snijding van de uittredende stralen. De reële/virtuele status van elk segment wordt automatisch gecorrigeerd.",
  "opt.info_lentille_divergente": "✏️ Zoals bij de bolle lens, maar het beeld is <strong>altijd virtueel</strong>: de uittredende stralen divergeren na de lens en moeten naar achteren (stippellijn) worden doorgetrokken om B' te construeren.",
  "opt.info_miroir_plan": "✏️ De leerling tekent de twee bijzondere stralen vanuit B (loodrechte inval, en een straal die bij S aankomt), laat ze weerkaatsen op de platte spiegel en construeert vervolgens B' door snijding van de doorgetrokken weerkaatste stralen. Het beeld is <strong>altijd virtueel en even groot</strong> als het voorwerp.",
  "opt.info_miroir_concave": "✏️ De leerling tekent minstens twee van de vier bijzondere stralen vanuit B (// as, via C, via F, naar S), laat ze weerkaatsen op de spiegel en construeert vervolgens B' door snijding van de weerkaatste stralen. Afhankelijk van de positie van het voorwerp (SA &lt; f of SA &gt; f) is het beeld virtueel of reëel — de verwachte reële/virtuele status van elk segment wordt automatisch gecorrigeerd.",
  "opt.info_miroir_convexe": "✏️ Zoals bij de holle spiegel, maar het brandpunt F en het middelpunt C zijn <strong>virtueel</strong> (achter de spiegel): het verkregen beeld is altijd virtueel, ongeacht de positie van het voorwerp.",
  "opt.info_lunette_galilee": "✏️ De leerling construeert vier bijzondere stralen: twee evenwijdige invallende stralen (één door het midden van het objectief) die samenkomen in B&#8321; in het gemeenschappelijke brandvlak, en vervolgens twee stralen vanuit B&#8321; naar het oculair, die evenwijdig naar buiten treden (afocaal systeem, beeld op oneindig). Het punt B&#8321; wordt geconstrueerd met het gereedschap „Snijpunt”.",
  "opt.info_telescope_newton": "✏️ De leerling construeert twee evenwijdige invallende stralen onder een hoek θ (één raakt de top S van de primaire spiegel, de andere is h verschoven) en hun bijbehorende weerkaatste stralen (gebruik „Spiegelen om as” voor de straal die bij de top wordt weerkaatst), die samenkomen in het beeldpunt B&#8321; in het brandvlak van de spiegel. Het punt B&#8321; wordt geconstrueerd met het gereedschap „Snijpunt”.",
  "opt.info_microscope": "✏️ De leerling tekent minstens twee van de drie bijzondere stralen vanuit B door het objectief L&#8321;, die samenkomen in B&#8321; (reëel tussenbeeld, geconstrueerd met „Snijpunt”), en vervolgens de twee stralen vanuit B&#8321; door het oculair L&#8322;, zo geplaatst dat B&#8321; precies in zijn voorwerpsbrandvlak ligt (instelling voor een normaal oog): de uittredende bundel komt evenwijdig naar buiten (eindbeeld op oneindig).",
