  "phy.enonce_chute_h": "Een voorwerp wordt losgelaten zonder beginsnelheid (vrije val, luchtweerstand verwaarloosd, \\(g=9{,}81\\) m/s²). Bereken de valhoogte \\(h\\) na een tijd \\(t={@{t}@}\\) s.",
  "phy.enonce_chute_t": "Een voorwerp wordt losgelaten zonder beginsnelheid vanaf een hoogte \\(h={@{h}@}\\) m (vrije val, \\(g=9{,}81\\) m/s²). Bereken de valtijd \\(t\\).",
  "phy.enonce_ec": "Bereken de kinetische energie \\(E_c\\) van een voorwerp met massa \\(m={@{m}@}\\) kg dat beweegt met snelheid \\(v={@{v}@}\\) m/s.",
  "phy.enonce_ep": "Bereken de zwaarte-energie \\(E_p\\) van een voorwerp met massa \\(m={@{m}@}\\) kg op een hoogte \\(h={@{h}@}\\) m boven de grond (\\(g=9{,}81\\) m/s²).",
  "phy.enonce_em_conserv": "Een voorwerp met massa \\(m\\) wordt losgelaten zonder beginsnelheid vanaf een hoogte \\(h={@{h}@}\\) m. Bereken, wrijving verwaarloosd, de grootte van zijn snelheid \\(v\\) net voor het inslaan op de grond (behoud van mechanische energie, \\(g=9{,}81\\) m/s²).",
  "phy.enonce_newton_f": "Een voorwerp met massa \\(m={@{m}@}\\) kg ondergaat een versnelling met grootte \\(a={@{a}@}\\) m/s². Bereken de grootte van de resulterende kracht \\(F\\) (2e wet van Newton, \\(F=ma\\)).",
